MOTIF_NAME = 'edge_zone_radial_influence_advantage'
MOTIF_DESCRIPTION = 'Scores empty edge-zone intersections by inverse-distance weighted stones within a 3x3 Chebyshev radius and returns True if the evaluated side controls at least five more edge-zone points than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    wt = (0.0, 4.0, 2.0, 1.0)
    cctl = 0
    octl = 0
    for r in range(19):
        row = board_rows[r]
        in_r = r <= 2 or r >= 16
        for c in range(19):
            if row[c] != '.':
                continue
            if not (in_r or c <= 2 or c >= 16):
                continue
            ci = 0.0
            oi = 0.0
            for dr in range(-3, 4):
                nr = r + dr
                if nr < 0 or nr >= 19:
                    continue
                r2 = board_rows[nr]
                for dc in range(-3, 4):
                    d = max(abs(dr), abs(dc))
                    if d == 0:
                        continue
                    if d > 3:
                        continue
                    nc = c + dc
                    if nc < 0 or nc >= 19:
                        continue
                    v = r2[nc]
                    if v == color:
                        ci += wt[d]
                    elif v == opp:
                        oi += wt[d]
            if ci - oi > 1.0:
                cctl += 1
            elif oi - ci > 1.0:
                octl += 1
    return cctl - octl >= 5

MOTIF_NAME = 'thick_contact_fight_support_advantage'
MOTIF_DESCRIPTION = 'For each same-color stone orthogonally adjacent to an enemy stone, scores its local support by same-color stones within Manhattan distance two capped at four plus a base contact point, returning True if the evaluated side leads this contact-thickness score by at least ten.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = [(-1,0),(1,0),(0,-1),(0,1)]

    def score(side, enemy):
        total = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != side:
                    continue
                in_contact = False
                for dr, dc in DIRS:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == enemy:
                        in_contact = True
                        break
                if not in_contact:
                    continue
                sup = 0
                for dr in range(-2, 3):
                    for dc in range(-2, 3):
                        if dr == 0 and dc == 0:
                            continue
                        if abs(dr) + abs(dc) > 2:
                            continue
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == side:
                            sup += 1
                total += min(sup, 4) + 1
        return total

    own = score(color, opp)
    oth = score(opp, color)
    return own - oth >= 10 and own >= 12

MOTIF_NAME = 'eye_security_capture_pressure_advantage'
MOTIF_DESCRIPTION = 'Scores stones with true-eye life and capture pressure from strong adjacent groups; returns True if the evaluated side leads by six combined secure/attacking points.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    gid = [[-1] * 19 for _ in range(19)]
    gcol, gsize, glibs, geyes = [], [], [], []
    for r in range(19):
        row = board_rows[r]
        for c in range(19):
            v = row[c]
            if v == '.' or gid[r][c] != -1:
                continue
            g = len(gcol)
            col = v
            stack = [(r, c)]
            gid[r][c] = g
            libs = set()
            sz = 0
            while stack:
                cr, cc = stack.pop()
                sz += 1
                for nr, nc in ((cr+1, cc), (cr-1, cc), (cr, cc+1), (cr, cc-1)):
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        ch = board_rows[nr][nc]
                        if ch == '.':
                            libs.add((nr, nc))
                        elif ch == col and gid[nr][nc] == -1:
                            gid[nr][nc] = g
                            stack.append((nr, nc))
            gcol.append(col)
            gsize.append(sz)
            glibs.append(len(libs))
            geyes.append(0)
    n = len(gcol)
    gadj = [set() for _ in range(n)]
    for r in range(19):
        for c in range(19):
            v = board_rows[r][c]
            if v == '.':
                continue
            i = gid[r][c]
            for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    ch = board_rows[nr][nc]
                    if ch != '.' and ch != v and gid[nr][nc] != i:
                        gadj[i].add(gid[nr][nc])
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] != '.':
                continue
            first = -1
            ec = None
            ok = True
            for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < 19 and 0 <= nc < 19):
                    continue
                ch = board_rows[nr][nc]
                if ch == '.':
                    ok = False
                    break
                if ec is None:
                    ec = ch
                    first = gid[nr][nc]
                elif ch != ec or gid[nr][nc] != first:
                    ok = False
                    break
            if not ok or ec is None:
                continue
            oc = 'W' if ec == 'B' else 'B'
            bad = 0
            for dr, dc in ((1,1), (1,-1), (-1,1), (-1,-1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == oc:
                    bad += 1
            if bad <= 1:
                geyes[first] += 1
    cmass = omass = cpress = opress = 0
    for i in range(n):
        e = geyes[i]
        l = glibs[i]
        if l >= 2 and (e >= 2 or (e >= 1 and l >= 5)):
            mass = gsize[i] + e
            if gcol[i] == color:
                cmass += mass
            else:
                omass += mass
        if e < 2 and l <= 2:
            atk = opp if gcol[i] == color else color
            strong = 0
            for j in gadj[i]:
                if gcol[j] == atk and glibs[j] >= 3:
                    strong += 1
            if strong:
                p = gsize[i] * (3 - l) * min(strong, 2)
                if gcol[i] == opp:
                    cpress += p
                else:
                    opress += p
    return (cmass + cpress) - (omass + opress) >= 6

MOTIF_NAME = 'crosscut_splitting_pressure_advantage'
MOTIF_DESCRIPTION = 'Detects 2x2 diagonal crosscuts and scores ones where the evaluated side\'s diagonal stones belong to stronger groups than the opponent\'s diagonal stones, weighting by opponent mass, liberty margin, and connected-splitting shape, returning True if the evaluated side leads this crosscut pressure by at least five with at least eight points.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    D = ((-1, 0), (1, 0), (0, -1), (0, 1))
    gid = [[-1] * 19 for _ in range(19)]
    gl = []
    gs = []
    seen = [[False] * 19 for _ in range(19)]
    ng = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] == '.' or seen[r][c]:
                continue
            ch = board_rows[r][c]
            st = [(r, c)]
            seen[r][c] = True
            libs = set()
            sz = 0
            while st:
                cr, cc = st.pop()
                gid[cr][cc] = ng
                sz += 1
                for dr, dc in D:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == ch and not seen[nr][nc]:
                            seen[nr][nc] = True
                            st.append((nr, nc))
                        elif v == '.':
                            libs.add((nr, nc))
            gl.append(len(libs))
            gs.append(sz)
            ng += 1

    def score(side: str) -> int:
        other = 'W' if side == 'B' else 'B'
        total = 0
        for r in range(18):
            for c in range(18):
                a = board_rows[r][c]
                b = board_rows[r][c + 1]
                d = board_rows[r + 1][c]
                e = board_rows[r + 1][c + 1]
                if a == side and e == side and b == other and d == other:
                    own_ids = {gid[r][c], gid[r + 1][c + 1]}
                    opp_ids = {gid[r][c + 1], gid[r + 1][c]}
                elif b == side and d == side and a == other and e == other:
                    own_ids = {gid[r][c + 1], gid[r + 1][c]}
                    opp_ids = {gid[r][c], gid[r + 1][c + 1]}
                else:
                    continue
                oml = min(gl[i] for i in own_ids)
                pml = min(gl[i] for i in opp_ids)
                if pml <= 4 and oml >= pml + 2:
                    w = 2 + sum(gs[i] for i in opp_ids) + min(oml - pml, 4)
                    if len(own_ids) == 1 and len(opp_ids) >= 2:
                        w += 2
                    if oml >= 5:
                        w += 1
                    total += w
        return total

    own = score(color)
    oth = score(opp)
    return own >= 8 and own - oth >= 5

MOTIF_NAME = 'low_liberty_group_attack_coverage_advantage'
MOTIF_DESCRIPTION = 'Finds enemy groups with exactly 2 or 3 liberties and counts their liberties touched by strong same-color attacker stones, returning True if the evaluated side leads this attack-coverage score by at least 5 with at least 6 of its own.'

def motif(board_rows: list[str], color: str) -> bool:
    DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))
    id_at = [[-1] * 19 for _ in range(19)]
    groups = []

    for r in range(19):
        for c in range(19):
            if board_rows[r][c] == '.' or id_at[r][c] != -1:
                continue
            stone = board_rows[r][c]
            stack = [(r, c)]
            comp = []
            libs = set()
            seen = set()
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in seen:
                    continue
                seen.add((cr, cc))
                comp.append((cr, cc))
                for dr, dc in DIRS:
                    nr, nc = cr + dr, cc + dc
                    if not (0 <= nr < 19 and 0 <= nc < 19):
                        continue
                    v = board_rows[nr][nc]
                    if v == stone:
                        if (nr, nc) not in seen:
                            stack.append((nr, nc))
                    elif v == '.':
                        libs.add((nr, nc))
            gid = len(groups)
            groups.append((stone, comp, libs))
            for cr, cc in comp:
                id_at[cr][cc] = gid

    def pressure(att, defender):
        total = 0
        for gidx, (gc, comp, libs) in enumerate(groups):
            if gc != defender:
                continue
            L = len(libs)
            if L not in (2, 3):
                continue
            covered = 0
            for lr, lc in libs:
                ok = False
                for dr, dc in DIRS:
                    nr, nc = lr + dr, lc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == att:
                        aid = id_at[nr][nc]
                        if len(groups[aid][2]) >= 3:
                            ok = True
                            break
                if ok:
                    covered += 1
            if covered:
                total += covered * (5 - L) + len(comp) // 3
        return total

    opp = 'W' if color == 'B' else 'B'
    own = pressure(color, opp)
    oth = pressure(opp, color)
    return own - oth >= 5 and own >= 6

MOTIF_NAME = 'diag_backed_weak_liberty_threat_advantage'
MOTIF_DESCRIPTION = 'Counts same-color stones with at least one diagonal same-color supporter of a distinct group with 3+ liberties, that are orthogonally adjacent to a liberty point of a weak opponent group (3 libs or fewer), weighted by supporter count, weak-liberty count, and proximity to atari, returning True if the evaluated side leads by at least three with at least four attacker-pressure points.'

def motif(board_rows, color):
    opp = 'W' if color == 'B' else 'B'
    D = ((-1,0),(1,0),(0,-1),(0,1))
    DG = ((-1,-1),(-1,1),(1,-1),(1,1))
    gid = [[-1] * 19 for _ in range(19)]
    glib = []
    n = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] == '.' or gid[r][c] != -1:
                continue
            ch = board_rows[r][c]
            st = [(r, c)]
            gid[r][c] = n
            libs = set()
            while st:
                cr, cc = st.pop()
                for dr, dc in D:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == ch and gid[nr][nc] == -1:
                            gid[nr][nc] = n
                            st.append((nr, nc))
                        elif v == '.':
                            libs.add((nr, nc))
            glib.append(len(libs))
            n += 1

    def score(side):
        other = 'W' if side == 'B' else 'B'
        total = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != side:
                    continue
                my_g = gid[r][c]
                diags = 0
                for dr, dc in DG:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == side:
                        sg = gid[nr][nc]
                        if sg != my_g and glib[sg] >= 3:
                            diags += 1
                if diags == 0:
                    continue
                wlib_cnt = 0
                min_opp = 99
                for dr, dc in D:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < 19 and 0 <= nc < 19) or board_rows[nr][nc] != '.':
                        continue
                    hit = False
                    for dr2, dc2 in D:
                        nr2, nc2 = nr + dr2, nc + dc2
                        if 0 <= nr2 < 19 and 0 <= nc2 < 19 and board_rows[nr2][nc2] == other:
                            g2 = gid[nr2][nc2]
                            if glib[g2] <= 3:
                                hit = True
                                if glib[g2] < min_opp:
                                    min_opp = glib[g2]
                    if hit:
                        wlib_cnt += 1
                if wlib_cnt > 0:
                    pressure = 4 - min_opp if min_opp < 99 else 0
                    total += diags * 2 + wlib_cnt + pressure
        return total

    own = score(color)
    oth = score(opp)
    return own >= 4 and own - oth >= 3

MOTIF_NAME = 'core_supported_cluster_dominance'
MOTIF_DESCRIPTION = 'Weights each stone by a compact-connectivity index over orthogonal links (base 2) plus diagonal links (base 2), scaled +2/-2 per stone, and returns True when the evaluated side leads by at least nine weighted points.'
def motif(board_rows: list[str], color: str) -> bool:
    if len(board_rows) != 19:
        return False
    opp = 'W' if color == 'B' else 'B'
    s = 0.0
    for r in range(19):
        row = board_rows[r]
        for c in range(19):
            ch = row[c]
            if ch == '.':
                continue
            u = 1
            if r > 0 and board_rows[r-1][c] == ch:
                u += 1
            if r+1 < 19 and board_rows[r+1][c] == ch:
                u += 1
            if c > 0 and row[c-1] == ch:
                u += 1
            if c+1 < 19 and row[c+1] == ch:
                u += 1
            w = 0
            if r > 0 and c > 0 and board_rows[r-1][c-1] == ch:
                w += 1
            if r > 0 and c+1 < 19 and board_rows[r-1][c+1] == ch:
                w += 1
            if r+1 < 19 and c > 0 and board_rows[r+1][c-1] == ch:
                w += 1
            if r+1 < 19 and c+1 < 19 and board_rows[r+1][c+1] == ch:
                w += 1
            val = 2 + u + 0.5*w
            s += val if ch == color else -val
    return s >= 9.0

MOTIF_NAME = 'enclosed_interval_attack_pressure_advantage'
MOTIF_DESCRIPTION = 'Scores same-color or edge-bounded row/column empty intervals of length 2-7 and attack pressure from low-liberty groups, returning True if the evaluated side leads the combined differential by at least 16.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    own_line = 0
    opp_line = 0
    lines = board_rows + [''.join(board_rows[r][c] for r in range(19)) for c in range(19)]
    for line in lines:
        i = 0
        while i < 19:
            if line[i] != '.':
                i += 1
                continue
            start = i
            while i < 19 and line[i] == '.':
                i += 1
            L = i - start
            if L < 2 or L > 7:
                continue
            left = line[start - 1] if start > 0 else 'E'
            right = line[i] if i < 19 else 'E'
            bs = {left, right}
            bs.discard('E')
            if bs == {color}:
                own_line += L
            elif bs == {opp}:
                opp_line += L
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    seen = [[False] * 19 for _ in range(19)]
    own_pres = 0
    opp_pres = 0
    for r in range(19):
        for c in range(19):
            ch = board_rows[r][c]
            if ch == '.' or seen[r][c]:
                continue
            seen[r][c] = True
            q = [(r, c)]
            idx = 0
            size = 0
            libs = set()
            while idx < len(q):
                cr, cc = q[idx]
                idx += 1
                size += 1
                for dr, dc in dirs:
                    nr = cr + dr
                    nc = cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == '.':
                            if len(libs) < 4:
                                libs.add((nr, nc))
                        elif v == ch and not seen[nr][nc]:
                            seen[nr][nc] = True
                            q.append((nr, nc))
            lc = len(libs)
            pres = size * (4 - lc) if lc <= 3 else 0
            if ch == color:
                own_pres += pres
            else:
                opp_pres += pres
    return (own_line - opp_line) + (opp_pres - own_pres) >= 16

MOTIF_NAME = 'group_linking_keypoint_advantage'
MOTIF_DESCRIPTION = 'Computes group IDs and sizes once, then counts empty intersections orthogonally adjacent to two or more distinct same-color groups (combined size at least four) with no opponent stone directly adjacent, weighting each by group count and total size, returning True if the evaluated side leads by at least three with at least four.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))
    seen = [[False] * 19 for _ in range(19)]
    gid_at = [[-1] * 19 for _ in range(19)]
    gsz = []
    n = 0
    for r in range(19):
        for c in range(19):
            ch = board_rows[r][c]
            if ch == '.' or seen[r][c]:
                continue
            st = [(r, c)]
            sz = 0
            while st:
                cr, cc = st.pop()
                if seen[cr][cc]:
                    continue
                seen[cr][cc] = True
                gid_at[cr][cc] = n
                sz += 1
                for dr, dc in DIRS:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == ch and not seen[nr][nc]:
                            st.append((nr, nc))
            gsz.append(sz)
            n += 1

    def keys(side: str) -> int:
        other = 'W' if side == 'B' else 'B'
        total = 0
        for r in range(19):
            row = board_rows[r]
            for c in range(19):
                if row[c] != '.':
                    continue
                gids = set()
                opp_adj = False
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == side:
                            gids.add(gid_at[nr][nc])
                        elif v == other:
                            opp_adj = True
                if len(gids) < 2 or opp_adj:
                    continue
                s = sum(gsz[g] for g in gids)
                if s >= 4:
                    total += (len(gids) - 1) + (2 if s >= 8 else 1)
        return total

    own = keys(color)
    oth = keys(opp)
    return own - oth >= 3 and own >= 4

MOTIF_NAME = 'floodfill_territory_dominance_advantage'
MOTIF_DESCRIPTION = 'Floodfills empty regions and scores each by capped area times net unique border-stone advantage, halving edge-touching regions, returning True if the evaluated side leads by at least 6 with at least 8 score.'

def motif(board_rows, color):
    opp = 'W' if color == 'B' else 'B'
    visited = [[False] * 19 for _ in range(19)]
    own_score = 0
    oth_score = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] != '.' or visited[r][c]:
                continue
            stack = [(r, c)]
            area = 0
            seen_o = set()
            seen_x = set()
            edge = False
            while stack:
                cr, cc = stack.pop()
                if visited[cr][cc]:
                    continue
                visited[cr][cc] = True
                area += 1
                if cr == 0 or cr == 18 or cc == 0 or cc == 18:
                    edge = True
                for nr, nc in ((cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)):
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == '.' and not visited[nr][nc]:
                            stack.append((nr, nc))
                        elif v == color:
                            seen_o.add(nr * 20 + nc)
                        elif v == opp:
                            seen_x.add(nr * 20 + nc)
            ob = len(seen_o)
            tb = len(seen_x)
            if ob + tb == 0 or area < 2:
                continue
            eff_area = min(area, 20)
            factor = 0.5 if edge else 1.0
            if ob > tb:
                own_score += eff_area * (ob - tb) * factor
            elif tb > ob:
                oth_score += eff_area * (tb - ob) * factor
    return own_score - oth_score >= 6 and own_score >= 8

MOTIF_NAME = 'opp_heavily_surrounded_ko_groups_count'
MOTIF_DESCRIPTION = 'Counts distinct opponent groups whose perimeter is dominated by evaluated-side stones with no eye space and very few liberties, returning True if the opponent has more such surrounded weak groups than the evaluated side has and at least two opposing ones.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))

    gid = [[-1] * 19 for _ in range(19)]
    info = []
    for r in range(19):
        for c in range(19):
            ch = board_rows[r][c]
            if ch == '.' or gid[r][c] != -1:
                continue
            gi = len(info)
            gid[r][c] = gi
            stack = [(r, c)]
            stones = []
            libs = set()
            lib_set = set()
            while stack:
                cr, cc = stack.pop()
                stones.append((cr, cc))
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == '.':
                            if len(libs) < 12:
                                libs.add((nr, nc))
                                lib_set.add((nr, nc))
                        elif v == ch and gid[nr][nc] == -1:
                            gid[nr][nc] = gi
                            stack.append((nr, nc))
            bset = set()
            for sr, sc in stones:
                for dr, dc in dirs:
                    nr, nc = sr + dr, sc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] != ch:
                        bset.add((nr, nc))
            info.append((ch, stones, libs, bset))

    diag = ((-1, -1), (-1, 1), (1, -1), (1, 1), (-2, 0), (2, 0), (0, -2), (0, 2))
    border_range = (-1, 0, 1)

    def has_eye(stones, libs, own):
        for lr, lcx in libs:
            ok = True
            own_cnt = 0
            for dr, dc in dirs:
                nr, nc = lr + dr, lcx + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    v = board_rows[nr][nc]
                    if v == '.':
                        ok = False
                        break
                    if v == own:
                        own_cnt += 1
            if ok and own_cnt + (4 - len(dirs)) >= 3:
                diag_same = 0
                for dr, dc in diag:
                    nr, nc = lr + dr, lcx + dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == own:
                        diag_same += 1
                if diag_same >= 3:
                    return True
        return False

    def weak_count(side):
        enemy = opp if side == color else color
        cnt = 0
        for ch, stones, libs, bset in info:
            if ch != side:
                continue
            nlibs = len(libs)
            if nlibs > 3:
                continue
            own_perim = 0
            en_perim = 0
            empty_perim = 0
            for pr, pc in bset:
                v = board_rows[pr][pc]
                if v == enemy:
                    own_perim += 1
                elif v == side:
                    en_perim += 1
                else:
                    empty_perim += 1
            total = own_perim + en_perim + empty_perim
            if total == 0:
                continue
            if own_perim < max(2, int(0.75 * total)):
                continue
            if has_eye(stones, libs, side):
                continue
            near_own = 0
            for sr, sc in stones:
                for dr in border_range:
                    for dc in border_range:
                        nr, nc = sr + dr, sc + dc
                        if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == enemy:
                            near_own += 1
            if len(stones) >= 2 and near_own >= 4 and en_perim == 0:
                cnt += 1
            elif len(stones) == 1 and own_perim >= 3 and en_perim == 0:
                cnt += 1
        return cnt

    own_weak = weak_count(color)
    opp_weak = weak_count(opp)
    return opp_weak >= 2 and opp_weak - own_weak >= 2

MOTIF_NAME = 'direct_atari_capture_mass_advantage'
MOTIF_DESCRIPTION = 'Counts stones in one-liberty atari groups for each side and returns True if the opponent has at least three more atari stones than the evaluated side.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))
    seen = [[False] * 19 for _ in range(19)]
    own = 0
    oth = 0
    for r in range(19):
        for c in range(19):
            if seen[r][c] or board_rows[r][c] == '.':
                continue
            ch = board_rows[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            size = 0
            libs = set()
            while stack:
                cr, cc = stack.pop()
                size += 1
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == '.':
                            if len(libs) < 2:
                                libs.add((nr, nc))
                        elif v == ch and not seen[nr][nc]:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
            if len(libs) == 1:
                mass = size if size == 1 else size * 2
                if ch == color:
                    own += mass
                else:
                    oth += mass
    return oth >= 3 and oth - own >= 3

MOTIF_NAME = 'intergroup_safe_knight_link_advantage'
MOTIF_DESCRIPTION = 'Counts safe knight-move links between distinct same-color groups with at least four liberties and both shoulder-cut points free of opponent stones; returns True if the evaluated side has at least four more such intergroup links than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    gid = [[-1] * 19 for _ in range(19)]
    glib = []

    for r in range(19):
        row = board_rows[r]
        for c in range(19):
            ch = row[c]
            if ch == '.' or gid[r][c] != -1:
                continue
            gi = len(glib)
            gid[r][c] = gi
            stack = [(r, c)]
            libs = set()
            while stack:
                cr, cc = stack.pop()
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == '.':
                            if len(libs) < 12:
                                libs.add((nr, nc))
                        elif v == ch and gid[nr][nc] == -1:
                            gid[nr][nc] = gi
                            stack.append((nr, nc))
            glib.append(len(libs))

    offs = [(2, 1), (2, -1), (1, 2), (1, -2)]

    def links(s: str) -> int:
        cnt = 0
        for r in range(19):
            row = board_rows[r]
            for c in range(19):
                if row[c] != s:
                    continue
                g1 = gid[r][c]
                if glib[g1] < 4:
                    continue
                for dr, dc in offs:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < 19 and 0 <= nc < 19):
                        continue
                    if board_rows[nr][nc] != s:
                        continue
                    g2 = gid[nr][nc]
                    if g1 == g2 or glib[g2] < 4:
                        continue
                    if abs(dr) == 2:
                        mr = r + 1
                        pts = ((mr, c), (mr, nc))
                    else:
                        mc = c + (1 if dc == 2 else -1)
                        pts = ((r, mc), (nr, mc))
                    ok = True
                    for pr, pc in pts:
                        if board_rows[pr][pc] == opp:
                            ok = False
                            break
                    if ok:
                        cnt += 1
        return cnt

    own = links(color)
    oth = links(opp)
    return own - oth >= 4 and own >= 5

MOTIF_NAME = 'edge_capture_press_advantage'
MOTIF_DESCRIPTION = 'Counts opponent stones on the first two edge lines that have a same-color stone directly perpendicular toward the center within two steps and whose group has at most eight liberties, returning True if the evaluated side leads by at least two with at least two of its own.'

def motif(board_rows, color):
    opp = 'W' if color == 'B' else 'B'
    D = ((-1,0),(1,0),(0,-1),(0,1))
    seen = [[False]*19 for _ in range(19)]
    gid = [[-1]*19 for _ in range(19)]
    glib = []
    n = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c]=='.' or seen[r][c]: continue
            ch = board_rows[r][c]
            st = [(r,c)]
            seen[r][c] = True
            libs = set()
            while st:
                cr, cc = st.pop()
                gid[cr][cc] = n
                for dr, dc in D:
                    nr, nc = cr+dr, cc+dc
                    if 0<=nr<19 and 0<=nc<19:
                        v = board_rows[nr][nc]
                        if v == ch and not seen[nr][nc]:
                            seen[nr][nc] = True
                            st.append((nr,nc))
                        elif v == '.':
                            libs.add((nr,nc))
            glib.append(len(libs))
            n += 1

    def score(side):
        oth = 'W' if side == 'B' else 'B'
        pressed = set()
        # Top edge
        for c in range(19):
            for r in (0, 1):
                if board_rows[r][c] != oth: continue
                if glib[gid[r][c]] > 8: continue
                for dr in (1, 2):
                    nr = r+dr
                    if nr < 19 and board_rows[nr][c] == side:
                        pressed.add((r, c))
                        break
        # Bottom edge
        for c in range(19):
            for r in (17, 18):
                if board_rows[r][c] != oth: continue
                if glib[gid[r][c]] > 8: continue
                for dr in (-1, -2):
                    nr = r+dr
                    if nr >= 0 and board_rows[nr][c] == side:
                        pressed.add((r, c))
                        break
        # Left edge
        for r in range(19):
            for c in (0, 1):
                if board_rows[r][c] != oth: continue
                if glib[gid[r][c]] > 8: continue
                for dc in (1, 2):
                    nc = c+dc
                    if nc < 19 and board_rows[r][nc] == side:
                        pressed.add((r, c))
                        break
        # Right edge
        for r in range(19):
            for c in (17, 18):
                if board_rows[r][c] != oth: continue
                if glib[gid[r][c]] > 8: continue
                for dc in (-1, -2):
                    nc = c+dc
                    if nc >= 0 and board_rows[r][nc] == side:
                        pressed.add((r, c))
                        break
        return len(pressed)

    own = score(color)
    oth = score(opp)
    return own >= 2 and own - oth >= 2

MOTIF_NAME = 'opponent_pinched_double_contact_advantage'
MOTIF_DESCRIPTION = 'Counts opponent stones orthogonally adjacent to at least two same-color stones with no orthogonal friendly support and a friendly majority on the diagonal points, returning True if the evaluated side leads this pinch score by at least three with at least four.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))
    DIAG = ((-1, -1), (-1, 1), (1, -1), (1, 1))

    def pinch(attacker: str) -> int:
        target = 'W' if attacker == 'B' else 'B'
        total = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != target:
                    continue
                own_cnt = 0
                fri_cnt = 0
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == attacker:
                            own_cnt += 1
                        elif v == target:
                            fri_cnt += 1
                if own_cnt < 2 or fri_cnt > 0:
                    continue
                diag_own = 0
                diag_opp = 0
                for dr, dc in DIAG:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == attacker:
                            diag_own += 1
                        elif v == target:
                            diag_opp += 1
                if diag_own > diag_opp:
                    total += 1 + diag_own - diag_opp
        return total

    own = pinch(color)
    oth = pinch(opp)
    return own - oth >= 3 and own >= 4

MOTIF_NAME = 'shape_defect_differential'
MOTIF_DESCRIPTION = 'Counts empty triangles (three same-color stones filling three corners of a 2x2 box with the fourth empty) and isolated low-liberty stones as shape defects; returns True if the opponent has at least three more defects than the evaluated side.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def libs(r, c):
        cnt = 0
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == '.':
                cnt += 1
        return cnt

    def count_def(s):
        d = 0
        # Empty triangles within 2x2 boxes (all four orientations handled by counting)
        for r in range(18):
            for c in range(18):
                sc = (board_rows[r][c] == s) + (board_rows[r+1][c] == s) + (board_rows[r][c+1] == s) + (board_rows[r+1][c+1] == s)
                ec = (board_rows[r][c] == '.') + (board_rows[r+1][c] == '.') + (board_rows[r][c+1] == '.') + (board_rows[r+1][c+1] == '.')
                if sc == 3 and ec == 1:
                    d += 1
        # Isolated low-liberty stones
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != s:
                    continue
                ally = False
                for dr in range(-2, 3):
                    if ally:
                        break
                    for dc in range(-2, 3):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == s:
                            ally = True
                            break
                if not ally and libs(r, c) <= 2:
                    d += 3
        return d

    return count_def(opp) - count_def(color) >= 3

MOTIF_NAME = 'hane_head_of_stones_pressure_advantage'
MOTIF_DESCRIPTION = 'Counts same-color stones orthogonally adjacent to an enemy stone that has another enemy neighbor (head of stones) where the same-color stone has a diagonal same-color supporter, returning True if the evaluated side leads hane-attack points by at least two with at least two of them.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    DIAGS = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    def at(r, c):
        if 0 <= r < 19 and 0 <= c < 19:
            return board_rows[r][c]
        return '.'

    def score(side, enemy):
        n = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != side:
                    continue
                dsup = 0
                for dr, dc in DIAGS:
                    if at(r + dr, c + dc) == side:
                        dsup += 1
                if dsup < 1:
                    continue
                hit = False
                for dr, dc in DIRS:
                    er, ec = r + dr, c + dc
                    if at(er, ec) != enemy:
                        continue
                    for dr2, dc2 in DIRS:
                        if (dr2, dc2) == (-dr, -dc):
                            continue
                        if at(er + dr2, ec + dc2) == enemy:
                            hit = True
                            break
                    if hit:
                        break
                if hit:
                    n += 1
        return n

    own = score(color, opp)
    oth = score(opp, color)
    return own - oth >= 2 and own >= 2

MOTIF_NAME = 'fourth_line_backed_third_line_stance_advantage'
MOTIF_DESCRIPTION = 'Counts evaluated-side stones on the third line from an edge that have a same-color stone on the adjacent fourth-line square (offset -1 to +1 perpendicular to that edge) plus a same-color stone within two steps along the same third line, returning True if the evaluated side leads by at least two and has at least three such stable fence stances.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    side = color
    def at(r, c, default='.'):
        if 0 <= r < 19 and 0 <= c < 19:
            return board_rows[r][c]
        return default
    def score(s):
        n = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != s:
                    continue
                add = False
                if r == 2:
                    backed = at(r + 1, c - 1) == s or at(r + 1, c) == s or at(r + 1, c + 1) == s
                    link = False
                    for dc in (1, 2, -1, -2):
                        if 0 <= c + dc < 19 and board_rows[r][c + dc] == s:
                            link = True
                            break
                    add = backed and link
                if not add and r == 16:
                    backed = at(r - 1, c - 1) == s or at(r - 1, c) == s or at(r - 1, c + 1) == s
                    link = False
                    for dc in (1, 2, -1, -2):
                        if 0 <= c + dc < 19 and board_rows[r][c + dc] == s:
                            link = True
                            break
                    add = backed and link
                if not add and c == 2:
                    backed = at(r - 1, c + 1) == s or at(r, c + 1) == s or at(r + 1, c + 1) == s
                    link = False
                    for dr in (1, 2, -1, -2):
                        if 0 <= r + dr < 19 and board_rows[r + dr][c] == s:
                            link = True
                            break
                    add = backed and link
                if not add and c == 16:
                    backed = at(r - 1, c - 1) == s or at(r, c - 1) == s or at(r + 1, c - 1) == s
                    link = False
                    for dr in (1, 2, -1, -2):
                        if 0 <= r + dr < 19 and board_rows[r + dr][c] == s:
                            link = True
                            break
                    add = backed and link
                if add:
                    n += 1
        return n
    own = score(side)
    oth = score(opp)
    return own - oth >= 2 and own >= 3

MOTIF_NAME = 'star_point_zone_control_advantage'
MOTIF_DESCRIPTION = 'Scores influence over the nine standard star points using nearby stones with distance decay; returns True if the evaluated side controls at least two more star-point zones than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    stars = [(3,3),(3,9),(3,15),(9,3),(9,9),(9,15),(15,3),(15,9),(15,15)]
    w = [1.0, 0.5, 0.25, 0.12]
    cctl = octl = 0
    for sr, sc in stars:
        ci = oi = 0.0
        for r in range(max(0, sr-3), min(19, sr+4)):
            row = board_rows[r]
            for c in range(max(0, sc-3), min(19, sc+4)):
                ch = row[c]
                if ch == '.':
                    continue
                d = max(abs(sr-r), abs(sc-c))
                if d > 3:
                    continue
                val = w[d]
                if ch == color:
                    ci += val
                else:
                    oi += val
        if ci - oi >= 0.5:
            cctl += 1
        elif oi - ci >= 0.5:
            octl += 1
    return cctl - octl >= 2

MOTIF_NAME = 'cardinal_enclosed_opponent_stones_advantage'
MOTIF_DESCRIPTION = 'Counts opponent stones for which the evaluated side has a stone first along at least three of four cardinal axes before another opponent stone or board edge appears within six steps, returning True if the evaluated side leads by at least three.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def score(side, enemy):
        total = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != enemy:
                    continue
                closed = 0
                for dr, dc in DIRS:
                    hit = False
                    for k in range(1, 7):
                        nr, nc = r + dr * k, c + dc * k
                        if not (0 <= nr < 19 and 0 <= nc < 19):
                            break
                        v = board_rows[nr][nc]
                        if v == side:
                            hit = True
                            break
                        if v == enemy:
                            break
                    if hit:
                        closed += 1
                if closed >= 3:
                    total += 1
        return total

    own = score(color, opp)
    oth = score(opp, color)
    return own - oth >= 3 and own >= 3

MOTIF_NAME = 'nearest_stone_influence_area_score'
MOTIF_DESCRIPTION = 'Estimates area score using alive stones, nearest-stone squared Euclidean controlled empty points, and atari stones, returning True if the evaluated side is ahead by at least 5 points.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    visited = [[False]*19 for _ in range(19)]
    color_coords = []
    opp_coords = []
    color_alive = 0
    opp_alive = 0
    color_dead = 0
    opp_dead = 0

    for r in range(19):
        for c in range(19):
            if board_rows[r][c] != '.' and not visited[r][c]:
                q = [(r, c)]
                visited[r][c] = True
                grp = []
                libs = set()
                while q:
                    cr, cc = q.pop()
                    grp.append((cr, cc))
                    for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 19 and 0 <= nc < 19:
                            if board_rows[nr][nc] == '.':
                                libs.add((nr, nc))
                            elif board_rows[nr][nc] == board_rows[r][c] and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))
                if len(libs) <= 1:
                    if board_rows[r][c] == color:
                        color_dead += len(grp)
                    else:
                        opp_dead += len(grp)
                else:
                    if board_rows[r][c] == color:
                        color_alive += len(grp)
                        color_coords.extend(grp)
                    else:
                        opp_alive += len(grp)
                        opp_coords.extend(grp)

    if color_alive == 0 or opp_alive == 0:
        return False

    color_ctrl = 0
    opp_ctrl = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] == '.':
                min_c = 1000
                for sr, sc in color_coords:
                    dr = r - sr
                    dc = c - sc
                    d = dr * dr + dc * dc
                    if d < min_c:
                        if d <= 2:
                            min_c = d
                            break
                        min_c = d
                min_o = 1000
                for sr, sc in opp_coords:
                    dr = r - sr
                    dc = c - sc
                    d = dr * dr + dc * dc
                    if d < min_o:
                        if d <= 2:
                            min_o = d
                            break
                        min_o = d
                if min_c < min_o:
                    color_ctrl += 1
                elif min_o < min_c:
                    opp_ctrl += 1

    color_score = color_alive + color_ctrl + opp_dead
    opp_score = opp_alive + opp_ctrl + color_dead
    return color_score > opp_score + 5

MOTIF_NAME = 'diagonal_chain_open_framework_barrier_advantage'
MOTIF_DESCRIPTION = 'Counts straight diagonal same-color chains of length>=3 with large perpendicular open space and minimal opponent contact; returns True if the evaluated side leads this diagonal-framework score by at least 5 with at least 6.'

def motif(board_rows, color):
    dirs = ((1, 1), (1, -1))

    def score(side):
        oth = 'W' if side == 'B' else 'B'
        total = 0
        for cdr, cdc in dirs:
            perps = ((cdc, -cdr), (-cdc, cdr))
            seen = set()
            for r in range(19):
                for c in range(19):
                    if board_rows[r][c] != side or (r, c) in seen:
                        continue
                    chain = []
                    rr, cc = r, c
                    while 0 <= rr < 19 and 0 <= cc < 19 and board_rows[rr][cc] == side and (rr, cc) not in seen:
                        seen.add((rr, cc))
                        chain.append((rr, cc))
                        rr += cdr
                        cc += cdc
                    L = len(chain)
                    if L < 3:
                        continue
                    open_cnt = 0
                    enemy_cnt = 0
                    for (br, bc) in chain:
                        for pdr, pdc in perps:
                            for off in (1, 2):
                                tr, tc = br + pdr * off, bc + pdc * off
                                if 0 <= tr < 19 and 0 <= tc < 19:
                                    v = board_rows[tr][tc]
                                    if v == '.':
                                        open_cnt += 1
                                    elif v == oth:
                                        enemy_cnt += 1
                    if open_cnt >= L and enemy_cnt <= 1:
                        total += L * 2 + open_cnt - 2 * enemy_cnt
        return total

    own = score(color)
    oth = score('W' if color == 'B' else 'B')
    return own >= 6 and own - oth >= 5

MOTIF_NAME = 'eyeless_squeezed_encirclement_advantage'
MOTIF_DESCRIPTION = 'Detects opponent groups of size>=3 with 0-1 true eyes whose outside liberties all touch evaluated-side stones, with an adjacent stronger same-color group, returning True if evaluated side leads this encirclement mass by at least 5 with at least 8 of its own.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    D = ((-1, 0), (1, 0), (0, -1), (0, 1))
    DG = ((-1, -1), (-1, 1), (1, -1), (1, 1))
    gid = [[-1] * 19 for _ in range(19)]
    gch = []
    gsz = []
    glb = []
    glbs = []
    gsts = []
    n = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] == '.' or gid[r][c] != -1:
                continue
            ch = board_rows[r][c]
            st = [(r, c)]
            gid[r][c] = n
            libs = set()
            sts = []
            while st:
                cr, cc = st.pop()
                sts.append((cr, cc))
                for dr, dc in D:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == ch and gid[nr][nc] == -1:
                            gid[nr][nc] = n
                            st.append((nr, nc))
                        elif v == '.':
                            libs.add((nr, nc))
            gch.append(ch)
            gsz.append(len(sts))
            glb.append(len(libs))
            glbs.append(list(libs))
            gsts.append(sts)
            n += 1

    def score(side: str) -> int:
        oth = 'W' if side == 'B' else 'B'
        total = 0
        for g in range(n):
            if gch[g] != oth:
                continue
            if gsz[g] < 3:
                continue
            if glb[g] > 5:
                continue

            open_libs = 0
            for r, c in glbs[g]:
                touched = False
                for dr, dc in D:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == side:
                        touched = True
                        break
                if not touched:
                    diag_side = 0
                    off_board = 0
                    for dr, dc in DG:
                        nr, nc = r + dr, c + dc
                        if not (0 <= nr < 19 and 0 <= nc < 19):
                            off_board += 1
                        elif board_rows[nr][nc] == side:
                            diag_side += 1
                    if diag_side + off_board >= 3 and diag_side >= 1:
                        touched = True
                if not touched:
                    open_libs += 1

            if open_libs > 1:
                continue
            if glb[g] == open_libs:
                continue

            adj_my = set()
            for r, c in gsts[g]:
                for dr, dc in D:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == side:
                        adj_my.add(gid[nr][nc])

            strong = False
            for nb in adj_my:
                ln = glb[nb]
                if (ln > glb[g] and ln >= 3) or (glb[g] <= 2 and ln >= 4) or (glb[g] == 1 and ln >= 2):
                    strong = True
                    break
            if not strong:
                if adj_my and sum(glb[nb] for nb in adj_my) > glb[g] + 2:
                    strong = True
            if not strong:
                continue

            total += gsz[g] + (1 - open_libs) * 4 + (5 - min(glb[g], 4))
        return total

    own = score(color)
    oth = score(opp)
    return own >= 8 and own - oth >= 5

MOTIF_NAME = 'cardinal_enclosure_dominance'
MOTIF_DESCRIPTION = 'Counts empty intersections where the nearest stone within five steps along at least two cardinal directions belongs to the evaluated side and no opponent stone appears in any cardinal direction; returns True if evaluated side leads by at least five such points.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    dirs = ((0, 1), (0, -1), (1, 0), (-1, 0))
    c_cnt = 0
    o_cnt = 0
    for r in range(19):
        row = board_rows[r]
        for c in range(19):
            if row[c] != '.':
                continue
            cl = 0
            ol = 0
            for dr, dc in dirs:
                nr = r + dr
                nc = c + dc
                d = 0
                while 0 <= nr < 19 and 0 <= nc < 19:
                    d += 1
                    ch = board_rows[nr][nc]
                    if ch != '.':
                        if d <= 5:
                            if ch == color:
                                cl += 1
                            else:
                                ol += 1
                        break
                    nr += dr
                    nc += dc
            if cl >= 2 and ol == 0:
                c_cnt += 1
            elif ol >= 2 and cl == 0:
                o_cnt += 1
    return c_cnt - o_cnt >= 5

MOTIF_NAME = 'rank8_quiet_safe_dominance'
MOTIF_DESCRIPTION = 'Counts rank-8 canvas adjacency for each side (default weak=3.0, winrate 0.55) with double bonus, subtract 2x rank-7, plus safe temple counts minus vulnerable temple counts, and the evaluated side leads by at least 4.'

def motif(board_rows: list[str], color: str) -> bool:
    if len(board_rows) < 19:
        return False
    opp = 'W' if color == 'B' else 'B'

    def score(side: str) -> float:
        s = 0.0
        # rank 8 = row index 7
        rank8 = 7
        if 0 <= rank8 < 19:
            row = board_rows[rank8]
            count_adj = 0
            for c in range(19):
                if row[c] == side:
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nr, nc = rank8 + dr, c + dc
                        if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == '.':
                            count_adj += 1
                            break
            s += 2.0 * count_adj

        # rank 7 = row index 6
        rank7 = 6
        if 0 <= rank7 < 19:
            row = board_rows[rank7]
            count7 = 0
            for c in range(19):
                if row[c] == side:
                    count7 += 1
            s -= 2.0 * count7

        # temples: 2x2 blocks of side stones; safe if no orth opponent adj, else vulnerable
        safe = 0
        vuln = 0
        for r in range(18):
            for c in range(18):
                if (board_rows[r][c] == side and board_rows[r][c + 1] == side and
                        board_rows[r + 1][c] == side and board_rows[r + 1][c + 1] == side):
                    has_opp = False
                    for tr, tc in ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)):
                        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            nr, nc = tr + dr, tc + dc
                            if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == opp:
                                has_opp = True
                                break
                        if has_opp:
                            break
                    if has_opp:
                        vuln += 1
                    else:
                        safe += 1
        s += safe - vuln
        return s

    return score(color) - score(opp) >= 4.0

MOTIF_NAME = 'supported_head_cap_pressure_advantage'
MOTIF_DESCRIPTION = 'Counts supported same-color stones capping the ends of opponent runs of length at least two along rows or columns, with no opponent branch beside the capped end; returns True if the evaluated side leads weighted cap pressure by at least four.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    perp_h = ((1, 0), (-1, 0))
    perp_v = ((0, 1), (0, -1))

    def pressure(s: str) -> int:
        t = opp if s == color else color
        w = 0

        def ok(hr, hc, odr, odc, endr, endc, perp):
            orw, ocw = hr + odr, hc + odc
            if 0 <= orw < 19 and 0 <= ocw < 19 and board_rows[orw][ocw] == t:
                return False
            sup = False
            if 0 <= orw < 19 and 0 <= ocw < 19 and board_rows[orw][ocw] == s:
                sup = True
            for pdr, pdc in perp:
                nr, nc = hr + pdr, hc + pdc
                if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == s:
                    sup = True
            if not sup:
                return False
            for pdr, pdc in perp:
                nr, nc = endr + pdr, endc + pdc
                if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == t:
                    return False
            return True

        for r in range(19):
            row = board_rows[r]
            c = 0
            while c < 19:
                if row[c] == t:
                    st = c
                    while c < 19 and row[c] == t:
                        c += 1
                    en = c - 1
                    ln = en - st + 1
                    if ln >= 2:
                        if st - 1 >= 0 and row[st - 1] == s and ok(r, st - 1, 0, -1, r, st, perp_h):
                            w += ln
                        if en + 1 < 19 and row[en + 1] == s and ok(r, en + 1, 0, 1, r, en, perp_h):
                            w += ln
                else:
                    c += 1

        for c in range(19):
            r = 0
            while r < 19:
                if board_rows[r][c] == t:
                    st = r
                    while r < 19 and board_rows[r][c] == t:
                        r += 1
                    en = r - 1
                    ln = en - st + 1
                    if ln >= 2:
                        if st - 1 >= 0 and board_rows[st - 1][c] == s and ok(st - 1, c, -1, 0, st, c, perp_v):
                            w += ln
                        if en + 1 < 19 and board_rows[en + 1][c] == s and ok(en + 1, c, 1, 0, en, c, perp_v):
                            w += ln
                else:
                    r += 1
        return w

    own = pressure(color)
    oth = pressure(opp)
    return own >= 4 and own - oth >= 4

MOTIF_NAME = 'thin_cutting_wedge_advantage'
MOTIF_DESCRIPTION = 'Counts small same-color stones (group size <=5, liberties >=3, at most one orthogonal same-side neighbor) orthogonally adjacent to at least two distinct opponent groups with one sized three or more; returns True if the evaluated side has at least two such wedges and at least one more than the opponent.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    D = ((-1,0),(1,0),(0,-1),(0,1))
    seen = [[False]*19 for _ in range(19)]
    gid = [[-1]*19 for _ in range(19)]
    glib = []
    gsz = []
    GID = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c] == '.' or seen[r][c]:
                continue
            ch = board_rows[r][c]
            st = [(r, c)]
            seen[r][c] = True
            libs = set()
            sz = 0
            while st:
                cr, cc = st.pop()
                gid[cr][cc] = GID
                sz += 1
                for dr, dc in D:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == ch and not seen[nr][nc]:
                            seen[nr][nc] = True
                            st.append((nr, nc))
                        elif v == '.':
                            libs.add((nr, nc))
            glib.append(len(libs))
            gsz.append(sz)
            GID += 1

    def score(side):
        other = 'W' if side == 'B' else 'B'
        total = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != side:
                    continue
                g = gid[r][c]
                if gsz[g] > 5 or glib[g] < 3:
                    continue
                own = 0
                opp_ids = set()
                for dr, dc in D:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == side:
                            own += 1
                        elif v == other:
                            opp_ids.add(gid[nr][nc])
                if own > 1:
                    continue
                if len(opp_ids) >= 2 and any(gsz[og] >= 3 for og in opp_ids):
                    total += 1
        return total

    own = score(color)
    oth = score(opp)
    return own - oth >= 1 and own >= 2

MOTIF_NAME = 'long_wall_run_advantage'
MOTIF_DESCRIPTION = 'Sums quadratically weighted lengths of orthogonal same-color stone runs of length at least 4 along rows and columns; returns True if the evaluated side leads the opponent by at least 6 weighted points.'
def motif(board_rows: list[str], color: str) -> bool:
    if len(board_rows) != 19:
        return False
    opp = 'W' if color == 'B' else 'B'

    def score(s: str) -> int:
        total = 0
        for r in range(19):
            row = board_rows[r]
            c = 0
            while c < 19:
                if row[c] != s:
                    c += 1
                    continue
                start = c
                while c < 19 and row[c] == s:
                    c += 1
                L = c - start
                if L >= 4:
                    total += L * L
        for c in range(19):
            r = 0
            while r < 19:
                if board_rows[r][c] != s:
                    r += 1
                    continue
                start = r
                while r < 19 and board_rows[r][c] == s:
                    r += 1
                L = r - start
                if L >= 4:
                    total += L * L
        return total

    return score(color) - score(opp) >= 6

MOTIF_NAME = 'isolated_medium_liberty_siege_pressure_advantage'
MOTIF_DESCRIPTION = 'Scores enemy groups with three to five liberties that lack a nearby stronger same-color helper and are in orthogonal contact with a stronger same-color attack group, weighted by stones, contacts, and liberty deficit, returning True if the evaluated side leads this siege pressure by at least four with at least five.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))
    PRX = ((-1,-1),(-1,1),(1,-1),(1,1),(-2,0),(2,0),(0,-2),(0,2),
           (-2,-1),(-2,1),(2,-1),(2,1),(-1,-2),(1,-2),(-1,2),(1,2))
    id_at = [[-1] * 19 for _ in range(19)]
    groups = []
    for r in range(19):
        for c in range(19):
            ch = board_rows[r][c]
            if ch == '.' or id_at[r][c] != -1:
                continue
            stack = [(r, c)]
            comp = []
            libs = set()
            while stack:
                cr, cc = stack.pop()
                if id_at[cr][cc] != -1:
                    continue
                id_at[cr][cc] = len(groups)
                comp.append((cr, cc))
                for dr, dc in DIRS:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = board_rows[nr][nc]
                        if v == ch and id_at[nr][nc] == -1:
                            stack.append((nr, nc))
                        elif v == '.':
                            libs.add((nr, nc))
            groups.append((ch, comp, libs))
    adj = [dict() for _ in groups]
    for r in range(19):
        for c in range(19):
            g = id_at[r][c]
            if g == -1:
                continue
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    h = id_at[nr][nc]
                    if h != -1 and h != g:
                        adj[g][h] = adj[g].get(h, 0) + 1

    def has_helper(gidx, defcol, Ld):
        comp = groups[gidx][1]
        for cr, cc in comp:
            for dr, dc in PRX:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    h = id_at[nr][nc]
                    if h != -1 and h != gidx and groups[h][0] == defcol and len(groups[h][2]) > Ld:
                        return True
        return False

    def score(att, defcol):
        total = 0
        for gidx, (gc, comp, libs) in enumerate(groups):
            if gc != defcol:
                continue
            Ld = len(libs)
            if Ld < 3 or Ld > 5:
                continue
            sz = len(comp)
            if sz < 2:
                continue
            if has_helper(gidx, defcol, Ld):
                continue
            attackers = []
            for h, cnt in adj[gidx].items():
                hg = groups[h]
                if hg[0] != att:
                    continue
                La = len(hg[2])
                if La >= Ld + 2 and La >= 4 and len(hg[1]) >= 2:
                    attackers.append(cnt)
            if not attackers:
                continue
            contacts = sum(attackers)
            total += sz * contacts * (6 - Ld) * (2 if len(attackers) >= 2 else 1)
        return total

    own = score(color, opp)
    oth = score(opp, color)
    return own - oth >= 4 and own >= 5

MOTIF_NAME = 'moyo_corridor_between_parallel_walls_advantage'
MOTIF_DESCRIPTION = 'Counts empty intersections in 1-3 wide vertical or horizontal corridors bounded by same-color stone runs of length at least 2 in distinct groups along the perpendicular axis, returning True if the evaluated side leads by at least 3 with at least 4.'

def motif(board_rows, color):
    opp = 'W' if color == 'B' else 'B'
    D = ((-1,0),(1,0),(0,-1),(0,1))
    seen = [[False]*19 for _ in range(19)]
    gid = [[-1]*19 for _ in range(19)]
    glib = []
    n = 0
    for r in range(19):
        for c in range(19):
            if board_rows[r][c]=='.' or seen[r][c]:
                continue
            ch = board_rows[r][c]
            st = [(r,c)]
            seen[r][c] = True
            libs = set()
            while st:
                cr,cc = st.pop()
                gid[cr][cc] = n
                for dr,dc in D:
                    nr,nc = cr+dr, cc+dc
                    if 0<=nr<19 and 0<=nc<19:
                        v = board_rows[nr][nc]
                        if v == ch and not seen[nr][nc]:
                            seen[nr][nc] = True
                            st.append((nr,nc))
                        elif v == '.':
                            libs.add((nr,nc))
            glib.append(len(libs))
            n += 1

    def score(side):
        other = 'W' if side == 'B' else 'B'
        total = 0
        for c1 in range(19):
            for c2 in range(c1+2, min(19, c1+5)):
                gap = c2 - c1 - 1
                if gap < 1 or gap > 3:
                    continue
                for r in range(19):
                    if board_rows[r][c1] != side or board_rows[r][c2] != side:
                        continue
                    opp_in = False
                    exp_in = 0
                    for cc in range(c1+1, c2):
                        v = board_rows[r][cc]
                        if v == other:
                            opp_in = True; break
                        if v == '.':
                            exp_in += 1
                    if opp_in or exp_in != gap:
                        continue
                    run1 = 1; rr = r-1
                    while rr>=0 and board_rows[rr][c1]==side:
                        run1 += 1; rr -= 1
                    rr = r+1
                    while rr<19 and board_rows[rr][c1]==side:
                        run1 += 1; rr += 1
                    run2 = 1; rr = r-1
                    while rr>=0 and board_rows[rr][c2]==side:
                        run2 += 1; rr -= 1
                    rr = r+1
                    while rr<19 and board_rows[rr][c2]==side:
                        run2 += 1; rr += 1
                    if run1 < 2 or run2 < 2:
                        continue
                    g1 = gid[r][c1]; g2 = gid[r][c2]
                    if g1 == g2:
                        continue
                    support = min(glib[g1], 5) + min(glib[g2], 5)
                    total += gap + min(support, 8)
        for r1 in range(19):
            for r2 in range(r1+2, min(19, r1+5)):
                gap = r2 - r1 - 1
                if gap < 1 or gap > 3:
                    continue
                for c in range(19):
                    if board_rows[r1][c] != side or board_rows[r2][c] != side:
                        continue
                    opp_in = False
                    exp_in = 0
                    for rr in range(r1+1, r2):
                        v = board_rows[rr][c]
                        if v == other:
                            opp_in = True; break
                        if v == '.':
                            exp_in += 1
                    if opp_in or exp_in != gap:
                        continue
                    run1 = 1; cc = c-1
                    while cc>=0 and board_rows[r1][cc]==side:
                        run1 += 1; cc -= 1
                    cc = c+1
                    while cc<19 and board_rows[r1][cc]==side:
                        run1 += 1; cc += 1
                    run2 = 1; cc = c-1
                    while cc>=0 and board_rows[r2][cc]==side:
                        run2 += 1; cc -= 1
                    cc = c+1
                    while cc<19 and board_rows[r2][cc]==side:
                        run2 += 1; cc += 1
                    if run1 < 2 or run2 < 2:
                        continue
                    g1 = gid[r1][c]; g2 = gid[r2][c]
                    if g1 == g2:
                        continue
                    support = min(glib[g1], 5) + min(glib[g2], 5)
                    total += gap + min(support, 8)
        return total

    own = score(color)
    oth = score(opp)
    return own >= 4 and own - oth >= 3

MOTIF_NAME = 'strong_group_open_expansion_headroom_advantage'
MOTIF_DESCRIPTION = 'For each same-color group of at least three stones with at least four liberties, counts its liberty points that are themselves adjacent to at least three empty intersections (open expansion headroom), returning True if the evaluated side leads by at least four with at least six.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))

    def open_headroom(target: str) -> int:
        seen = [[False] * 19 for _ in range(19)]
        total = 0
        for r in range(19):
            for c in range(19):
                if board_rows[r][c] != target or seen[r][c]:
                    continue
                st = [(r, c)]
                libs = set()
                sz = 0
                while st:
                    cr, cc = st.pop()
                    if seen[cr][cc]:
                        continue
                    seen[cr][cc] = True
                    sz += 1
                    for dr, dc in DIRS:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 19 and 0 <= nc < 19:
                            v = board_rows[nr][nc]
                            if v == target and not seen[nr][nc]:
                                st.append((nr, nc))
                            elif v == '.':
                                libs.add((nr, nc))
                if sz < 3 or len(libs) < 4:
                    continue
                for (lr, lc) in libs:
                    empty_n = 0
                    for dr, dc in DIRS:
                        nr, nc = lr + dr, lc + dc
                        if 0 <= nr < 19 and 0 <= nc < 19 and board_rows[nr][nc] == '.':
                            empty_n += 1
                    if empty_n >= 3:
                        total += 1
        return total

    own = open_headroom(color)
    oth = open_headroom(opp)
    return own - oth >= 4 and own >= 6
